function param<K extends ParamId>(id: K, value: ParamValues[K]): Param<ParamValues[K]> {
  return {
    id,
    value,
    meta: {
      unit: 'none',
      evidence: ['INF'],
      sources: ['src.powr-eb-load' as SourceId],
      ebRef: 'test fixture',
      verified: true,
      label: `params.${id}`,
      origin: 'default',
      defaultValue: value,
      outOfRange: false,
    },
  };
}

/** A full rule set from the EB defaults, with optional replacements. */
export function rules(overrides: Partial<ParamValues> = {}): RuleSet {
  const values = { ...EB_DEFAULTS, ...overrides };
  return Object.fromEntries(
    (Object.keys(values) as ParamId[]).map((id) => [id, param(id, values[id])]),
  ) as RuleSet;
}
